---
import Layout from '@/layouts/base.astro';
---

<Layout
  title="Subscribe to the Newsletter"
  description="Confirm your subscription to the Agile Pain Relief newsletter."
  noIndex={true}
  includeCoursesCTA={false}
  hideChrome={true}
>
  <main class="container mx-auto max-w-xl px-4 py-12">
    {/*
      Landing page for the post-course "Subscribe to the Newsletter" email link.
      The link points here with `?email=&custom_attributes[firstname]=&auto_submit=1`.
      Cakemail's form-prefill.js (loaded by the embed below) reads those params
      off this page's URL, fills the embedded Newsletter Subscribers form, and
      auto-submits it. The form handles list add + double opt-in; on submit the
      browser is sent to Cakemail's "check your inbox" page, and after the visitor
      confirms, the form's DOI redirect lands them on /newsletter-confirmed/.

      This is the Cakemail "dynamic embed" snippet (auto-updates if the form is
      edited in Cakemail). If the form is replaced, paste the new snippet here.
    */}
    <script is:inline id="form-script-vtBba0M7ISiWErZg2iSS">
      (function () {
        var FORM_CONTAINER_ID = null;

        var script = document.getElementById('form-script-vtBba0M7ISiWErZg2iSS');
        function insertContent(content) {
          var range = document.createRange();
          var fragment = range.createContextualFragment(content);
          if (FORM_CONTAINER_ID) {
            var container = document.getElementById(FORM_CONTAINER_ID);
            if (container) {
              container.appendChild(fragment);
              container.id = 'form-content-vtBba0M7ISiWErZg2iSS';
              return;
            }
            console.error('Container "' + FORM_CONTAINER_ID + '" not found');
            return;
          }

          var div = document.createElement('div');
          div.appendChild(fragment);
          div.id = 'form-content-vtBba0M7ISiWErZg2iSS';
          script && script.parentNode
            ? script.parentNode.insertBefore(div, script)
            : document.body.appendChild(div);
        }

        function loadFormPrefillScript() {
          if (document.querySelector('script[data-ck-form-prefill="loader"]')) return;
          var prefillScript = document.createElement('script');
          prefillScript.src = 'https://contentapi.wbsrvcx.com/scripts/form-prefill.js';
          prefillScript.defer = true;
          prefillScript.setAttribute('data-ck-form-prefill', 'loader');
          document.head.appendChild(prefillScript);
        }

        fetch(
          'https://api.cakemail.dev/forms/b35ad5e2ccd9e980eaaf5dce5dd73179f591e6fe075204973387094ce6aac3804dd4bed20374f8c4d9c9e2f2432fb46507bc5469ab3b8fbe/render-html',
        )
          .then((response) => {
            if (response.status === 200) return response.text();
            return response.json();
          })
          .then((content) => {
            if (typeof content === 'object') throw content;
            insertContent(content);
            loadFormPrefillScript();
          })
          .catch((error) => {
            console.error('Error loading form:', error);
          })
          .finally(() => {
            if (script) script.remove();
          });
      })();
    </script>
  </main>
</Layout>

